// IS THERE A CUSTOMER VOICE IN THIS TICKET AT ALL?
//
// SARCLA, 24.10.2026: "we should find a way even to disqualify some that are not real ticket".
// He is right, and it is measurable: of the 2,000 most recent Back-Office tickets, 10.9% are
// machine-generated by subject alone, and the biggest group - 151 order confirmations - had been
// given a real sentiment on 90 of them (57 positive, 33 negative). None of that is a customer
// being happy or unhappy; it is our own templates scoring against our own keyword lists, and it
// lands in every average the report would show.
//
// So the question is asked BEFORE any scoring: is there a human customer talking here? A ticket
// that fails is not "neutral" - it is not a candidate, it gets no sentiment, and it is counted
// under its reason so the exclusions can be argued with instead of hidden.
//
// Deliberately conservative: a ticket is only disqualified on evidence (a template subject, our
// own address, no inbound mail). "I am not sure" keeps the ticket. Being over-eager here would
// silently shrink the very report it is meant to clean.

import { mailText } from "./detect";

export type DisqualifyReason =
  | "erp_stale_warning" | "anyseals" | "directcut" | "doc_declaration"
  | "order_confirmation" | "shipping_notification" | "new_registrant"
  | "auto_reply" | "bounce" | "newsletter"
  | "no_inbound_mail" | "only_our_own_words"
  /** Bulk mail recognised from the body, not the subject: an unsubscribe footer and friends. */
  | "bulk_mail"
  /** The model's second opinion, recorded by the engine - the gate never sets this itself. */
  | "model_says_machine";

export type Verdict = {
  /** May this ticket carry a sentiment? */
  real: boolean;
  /** Why not, or empty. */
  reasons: DisqualifyReason[];
  /** Did somebody outside actually write into the thread? */
  customerVoice: boolean;
  /**
   * A real matter, but with nothing written in from outside to read a tone from.
   *
   * SARCLA, 25.10.2026, on 60.9% of the inbox being "not a customer": "for me it's crazy high".
   * He was right. Of 100 such tickets, 18 were genuine customer business that arrived by WEB FORM
   * or was raised by our own people for a customer - "Customer Form | Delivery: Existing Order",
   * "BO | Product Information | Raffaello Lonardi" - and they have no inbound e-mail object at
   * all. Treating that as "not a valid e-mail" said the customer did not exist, when what was
   * missing was only their words. Those tickets are real; their tone is unknown.
   */
  noCustomerWords: boolean;
};

/**
 * The one judgement call in this file, made a switch instead of a guess.
 *
 * A template subject means the MACHINE wrote the first mail - but a customer who replies
 * "perfect, thanks" to an order confirmation is a real voice, and the live data says this is
 * not rare: of 151 order confirmations in the recent sample, 90 carried a sentiment, 57 of them
 * positive. Dropping them all loses real signal; keeping them all lets a one-line pleasantry
 * flood the positive count. So the gate reports both facts and the report decides, with the
 * figure shown both ways. Default off: a clean report first, the wider one on request.
 */
export type GateOptions = { templateRepliesCount?: boolean };

/** What the gate reads. Everything optional: a missing field never disqualifies on its own. */
export type GateInput = {
  subject?: string | null;
  /** Each associated mail's direction, so "did a customer ever write" can be answered. */
  mails?: { direction?: string | null; from?: string | null; text?: string | null; html?: string | null }[];
};

/**
 * Subject patterns, each with the reason it stands for.
 *
 * Anchored where the template anchors it (a subject STARTS with "New registrant") and loose where
 * the ERP writes a prefix. Accent-insensitive: matched against the folded subject.
 */
const SUBJECT_RULES: { reason: DisqualifyReason; test: RegExp }[] = [
  { reason: "erp_stale_warning", test: /\berp order export stale\b/ },
  { reason: "anyseals", test: /\banyseals\b/ },
  { reason: "directcut", test: /^directcut\b|\bcut[- ]to[- ]size\b|\bzuschnitt\b/ },
  { reason: "doc_declaration", test: /\bdeclaration of conformity\b|\bseal declaration\b|\bkonformitatserklarung\b/ },
  { reason: "order_confirmation", test: /\border confirmation\b|\bauftragsbestatigung\b|\bconfirmation de commande\b|\bconferma d'?ordine\b/ },
  { reason: "shipping_notification", test: /\bshipping notification\b|\bversandbenachrichtigung\b|\bavis d'?expedition\b|\btracking (?:number|information)\b/ },
  { reason: "new_registrant", test: /^new registrant\b/ },
  { reason: "auto_reply", test: /\bautomatic reply\b|\bautomatische antwort\b|\bout of office\b|\babwesenheitsnotiz\b|\breponse automatique\b|\brisposta automatica\b/ },
  { reason: "bounce", test: /\bundeliverable\b|\bdelivery (?:has )?failed\b|\bmail delivery (?:failed|subsystem)\b|\bunzustellbar\b/ },
  { reason: "newsletter", test: /\bnewsletter\b|\bunsubscribe\b|\babmelden vom newsletter\b/ },
];

/**
 * Bulk mail recognised from the BODY.
 *
 * The subject rules miss third-party marketing entirely - a trade-fair mailing, a supplier's
 * promotional flyer, a vendor pitch all carry ordinary subjects from ordinary addresses. The
 * model caught 7 of 18 tickets as machine-generated that the subject rules had let through, and
 * they were all of this kind. An unsubscribe footer is the one thing bulk mail cannot hide.
 */
const BULK_STRONG = [
  "unsubscribe", "abmelden", "newsletter abbestellen", "se desabonner", "se désabonner",
  "desinscrire", "disiscriviti", "annulla iscrizione", "cancel subscription",
  "view this email in your browser", "im browser ansehen", "voir dans le navigateur",
];
const BULK_WEAK = [
  "newsletter", "privacy policy", "datenschutzerklarung", "politique de confidentialite",
  "manage preferences", "no longer wish to receive", "sie erhalten diese e-mail, weil",
  "promotion", "webinar", "trade fair", "exhibition", "dealerprijzen",
];

/** Does this inbound mail look like something sent to a list rather than to us? */
export function looksBulk(text: string): boolean {
  const t = fold(text);
  if (!t) return false;
  if (BULK_STRONG.some((m) => t.includes(m))) return true;
  return BULK_WEAK.filter((m) => t.includes(m)).length >= 2;
}

/** Our own senders: a mail from these is never "the customer talking". */
const OUR_DOMAINS = ["apsoparts.com", "angst-pfister.com", "apsoparts.de", "anyseals.com"];
const NO_REPLY = /\b(?:no[-.]?reply|donotreply|noreply|mailer-daemon|postmaster)\b/;

/** Accent- and case-folded, so one rule covers "Auftragsbestätigung" and "auftragsbestatigung". */
export function fold(s: string | null | undefined): string {
  return String(s ?? "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/\s+/g, " ").trim();
}

/** Did a real outside person write into this ticket? */
export function hasCustomerVoice(mails: GateInput["mails"]): boolean {
  for (const m of mails ?? []) {
    if ((m.direction || "") !== "INCOMING_EMAIL") continue;
    const from = fold(m.from);
    if (from && NO_REPLY.test(from)) continue;
    if (from && OUR_DOMAINS.some((d) => from.includes("@" + d) || from.endsWith(d))) continue;
    // One mail in five carries its words only in the HTML body, so asking for `text` alone would
    // call a real customer "our own words" and quietly drop the ticket out of the report.
    if (!mailText(m).trim()) continue;
    return true;
  }
  return false;
}

/**
 * Whether this ticket may carry a sentiment, and if not, why.
 *
 * Subject rules are collected rather than short-circuited: a report that says a ticket was
 * excluded for two reasons is more use than one that names whichever rule happened to run first.
 */
export function gate(input: GateInput, opts: GateOptions = {}): Verdict {
  const subject = fold(input.subject);
  const reasons: DisqualifyReason[] = [];
  if (subject) for (const r of SUBJECT_RULES) if (r.test.test(subject)) reasons.push(r.reason);
  const templates = reasons.length;

  // A ticket with no inbound mail has no customer tone to read. It may still be a real piece of
  // work (a colleague opened it by hand), which is why the reason says what is missing rather
  // than calling it machine-made.
  const mails = input.mails ?? [];
  const voice = hasCustomerVoice(mails);
  const inbound = mails.filter((m) => (m.direction || "") === "INCOMING_EMAIL");

  // NOTHING WRITTEN IN FROM OUTSIDE is not evidence of a machine. A web form, a chat, a phone
  // call and a ticket our own people raise for a customer all look exactly like this, and all of
  // them are real work. The ticket stays; only its tone is unknown.
  const noWords = inbound.length === 0;
  if (!noWords && !voice) reasons.push("only_our_own_words");
  else if (!noWords && inbound.every((m) => looksBulk(mailText(m)))) {
    // every inbound mail is bulk - if even one is a real letter, the ticket stays
    reasons.push("bulk_mail");
  }

  // A template the customer answered: real only when asked for, and never when the only reason
  // was that nobody outside wrote - that one is not a matter of taste.
  const templateOnly = templates > 0 && reasons.length === templates;
  const real = reasons.length === 0 || (templateOnly && voice && opts.templateRepliesCount === true);
  return { real, reasons, customerVoice: voice, noCustomerWords: noWords && real };
}

/** Every reason, with the words the report uses - so the tab and the tests cannot drift. */
export const REASON_LABEL: Record<DisqualifyReason, string> = {
  erp_stale_warning: "ERP stale-export warning",
  anyseals: "Anyseals list",
  directcut: "DirectCut / cut-to-size",
  doc_declaration: "Declaration of conformity",
  order_confirmation: "Order confirmation",
  shipping_notification: "Shipping notification",
  new_registrant: "New registrant",
  auto_reply: "Automatic reply / out of office",
  bounce: "Undeliverable / bounce",
  newsletter: "Newsletter",
  no_inbound_mail: "No mail from outside",
  only_our_own_words: "Mail from us or a no-reply robot",
  bulk_mail: "Bulk mail (unsubscribe footer)",
  model_says_machine: "The model says nobody is talking",
};
